fn pairwise_addition(a: Vec<i64>) -> Vec<i64> {
    // Since the input length is guaranteed to be even, we can safely take chunks of size 2.
    a.chunks(2)
     .map(|pair| pair[0] + pair[1])
     .collect()
}

